import java.nio.charset.StandardCharsets;

public class Main {
    static class Item {
        final int id;
        final String name;
        final double price;

        Item(int id, String name, double price) {
            this.id = id;
            this.name = name;
            this.price = price;
        }
    }

    public static void main(String[] args) throws IOException {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (DataOutputStream out = new DataOutputStream(bytes)) {
            writeItem(out, new Item(1, "键盘", 199.0));
            writeItem(out, new Item(2, "鼠标", 89.5));
            out.writeInt(-1);
        }
        System.out.println("bytes=" + bytes.size());
        int count = 0;
        double sum = 0.0;
        try (DataInputStream in = new DataInputStream(
                new ByteArrayInputStream(bytes.toByteArray()))) {
            while (true) {
                int id = in.readInt();
                if (id < 0) {
                    break;
                }
                byte[] raw = new byte[in.readUnsignedByte()];
                in.readFully(raw);
                double price = in.readDouble();
                count++;
                sum += price;
                System.out.println("item=" + id + " " + new String(raw, StandardCharsets.UTF_8));
            }
        }
        System.out.println("count=" + count);
        System.out.println("sum=" + sum);
    }

