        private Glyph(char symbol) {
            this.symbol = symbol;
        }

        @Override
        public String toString() {
            return String.valueOf(symbol);
        }
    }

    static final class GlyphFactory {
        private final Map<Character, Glyph> cache = new LinkedHashMap<>();

