import java.util.Arrays;

public class Main {
    static void bubbleSort(int[] values) {
        for (int i = 0; i < values.length - 1; i++) {
            for (int j = 0; j < values.length - 1 - i; j++) {
                if (values[j] > values[j + 1]) {
                    int temp = values[j];
                    values[j] = values[j + 1];
                    values[j + 1] = temp;
                }
            }
        }
    }

    static int binarySearch(int[] sorted, int target) {
        int low = 0;
        int high = sorted.length - 1;
        while (low <= high) {
            int mid = (low + high) >>> 1;
            if (sorted[mid] == target) {
                return mid;
            } else if (sorted[mid] < target) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        int[] values = {5, 2, 9, 1, 7};
        bubbleSort(values);
        System.out.println(Arrays.toString(values));
        System.out.println("index=" + binarySearch(values, 7));
        System.out.println("missing=" + binarySearch(values, 3));
    }
}

import java.util.Arrays;

public class Main {
    static long fib(int n, long[] memo) {
        if (n <= 1) {
            return n;
        }
        if (memo[n] != -1) {
            return memo[n];
        }
        memo[n] = fib(n - 1, memo) + fib(n - 2, memo);
        return memo[n];
    }

    public static void main(String[] args) {
        int n = 40;
        long[] memo = new long[n + 1];
        Arrays.fill(memo, -1);
        System.out.println("fib=" + fib(n, memo));
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Queue;

public class Main {
    public static void main(String[] args) {
        Map<String, List<String>> graph = new HashMap<>();
        graph.put("A", List.of("B", "C"));
        graph.put("B", List.of("D"));
        graph.put("C", List.of("D"));
        graph.put("D", List.of());

        List<String> order = new ArrayList<>();
        Queue<String> queue = new ArrayDeque<>();
        Map<String, Boolean> visited = new HashMap<>();
        queue.add("A");
        visited.put("A", true);
        while (!queue.isEmpty()) {
            String node = queue.poll();
            order.add(node);
            for (String next : graph.get(node)) {
                if (visited.putIfAbsent(next, true) == null) {
                    queue.add(next);
                }
            }
        }
        System.out.println(order);
    }
}

